import { marqueeItems } from "@/lib/config";

export default function Marquee() {
  const items = [...marqueeItems, ...marqueeItems]; // duplicate for seamless loop

  return (
    <div className="overflow-hidden border-y border-white/10 bg-[#111114]/90 py-4 backdrop-blur-md">
      <div className="marquee-track">
        {items.map((item, i) => (
          <span
            key={i}
            className="flex items-center text-xs font-semibold tracking-wider text-zinc-400 uppercase sm:text-sm"
          >
            <span className="px-6 hover:text-white transition-colors">{item}</span>
            <span className="text-red-500 text-xs" aria-hidden>
              ✦
            </span>
          </span>
        ))}
      </div>
    </div>
  );
}


